@spec arrange_view_spec  src=tests/specs/arrange_view_spec.lua  loc=941  cases=53
@exercises configManager (h.cm), arrangeView (av), commandManager (h.cmgr), arrangeManager (am2)
@surface   cm:set, av:cursorRow, av:cursorCol, av:setCursor, av:setGridSize, av:scroll, av:scrollBy, av:setMaxCol, av:beatPerRow, av:setBeatPerRow, cm:get, av:rowToQN, av:paletteSlot, av:setPaletteSlot, av:focus, av:setFocus, cmgr:push, cmgr:invoke, am2:tracksTakes, av:tracksTakes, av:lassoCandidate, av:selectionSet, av:isSelected, av:selectBand, cmgr:pop, av:dropBand, av:setSelection, av:addToSelection, av:toggleSelected, av:dragCandidate, av:commitDrag, am:loopRangeQN, am:editCursorQN, av:qnToRow
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.GetSetRepeat

# Intent
  arrangeView: in-memory cursor/scroll + persisted beatPerRow, mirroring
  the trackerView/editCursor split (cursor is transient, density persists).

# Helpers
  @fn mkAv(harness)  @ 7-13
  @fn mkArrange(harness, items)  @ 17-36
      -- Build an av over a fake project. items: list of {track, name, pos, len?}.
      -- Tracks are created in first-seen order; beatPerRow is 1 (1 row = 1 QN).
  @fn takeAt(list, startQN)  @ 38-40

# Cases
  @case 'cursor defaults to (0,0); setCursor clamps negatives and floors'  [harness]  @ 61-69
  @case 'scroll defaults to (0,0); setGridSize alone does not move scroll'  [harness]  @ 73-79
  @case 'cursor moving below the visible band scrolls down to follow'  [harness]  @ 83-90
  @case 'cursor moving above the visible band scrolls up to follow'  [harness]  @ 94-102
  @case 'horizontal follow tracks cursorCol against gridCols'  [harness]  @ 106-116
  @case 'setGridSize shrinking the viewport re-follows the cursor in place'  [harness]  @ 120-131
  @case 'scrollBy pans the viewport without moving the cursor'  [harness]  @ 135-144
  @case 'scrollBy clamps to >= 0 and cursor-nav re-follows the cursor'  [harness]  @ 148-159
  @case 'scroll-right stops once the last column is fully visible'  [harness]  @ 163-171
  @case 'a same-dims setGridSize after a wheel-scroll leaves scroll alone'  [harness]  @ 175-183
  @case 'beatPerRow defaults to cm value; setter clamps minimum'  [harness]  @ 187-196
  @case 'setBeatPerRow holds the cursor QN (zoom anchors on cursor) and clamps max'  [harness]  @ 200-212
  @case 'paletteSlot defaults nil; setter clamps to 0..61; nil clears'  [harness]  @ 216-230
  @case 'focus defaults nil; setFocus stores an opaque handle, nil clears'  [harness]  @ 234-243
  @case 'no selection + on-screen cursor: edit acts on the cursor take, leaves it unselected'  [harness]  @ 247-263
  @case 'no selection + off-screen cursor: an edit is a no-op'  [harness]  @ 267-283
  @case 'a held selection wins over the cursor take'  [harness]  @ 287-306
  @case 'lasso selects every take whose span intersects the swept rect'  [harness]  @ 310-326
  @case 'Shift+arrow selects every take the anchor-to-cursor rect covers'  [harness]  @ 330-343
  @case 'Shift+arrow sideways widens the rect into the next column'  [harness]  @ 347-358
  @case 'Shift+arrow back toward the anchor drops what it uncovers'  [harness]  @ 362-376
  @case 'a plain cursor move ends the run, so the next Shift+arrow re-anchors'  [harness]  @ 380-392
  @case 'a bare cursor move clears the selection'  [harness]  @ 396-406
  @case 'Home clears the selection like any other bare nav'  [harness]  @ 410-420
  @case 'Tab walks down the column, stopping at each start and each free row after a take'  [harness]  @ 424-442
  @case 'abutting takes collapse their shared boundary to one Tab stop'  [harness]  @ 446-457
  @case 'Shift+Tab walks back up, snapping to the start of the take it is inside'  [harness]  @ 461-475
  @case 'Tab only sees the takes in the cursor column'  [harness]  @ 479-492
  @case 'Tab clears the selection like any other bare nav'  [harness]  @ 496-507
  @case 'an edit's own cursor advance keeps the selection'  [harness]  @ 511-522
  @case 'the pooled duplicate clears the selection and lands the caret on the copy'  [harness]  @ 526-543
  @case 'the band stands through a run and comes down on the next command'  [harness]  @ 547-565
  @case 'a click takes the band down without waiting for a command'  [harness]  @ 569-580
  @case 'dropBand takes the band down and pops its scope'  [harness]  @ 584-594
  @case 'a multi-selection deletes every selected take in one pass'  [harness]  @ 598-612
  @case 'nudge refuses entirely when any selected take is blocked'  [harness]  @ 616-633
  @case 'nudge slides a contiguous selected block without self-collision'  [harness]  @ 637-652
  @case 'a single-target command no-ops on a multi-selection'  [harness]  @ 656-669
  @case 'arrangeClearSelection empties the selection'  [harness]  @ 673-684
  @case 'addToSelection unions handles without duplicating a present one'  [harness]  @ 688-702
  @case 'toggleSelected adds an absent handle and removes a present one'  [harness]  @ 706-719
  @case 'group drag slides the whole selection by one delta'  [harness]  @ 723-739
  @case 'group drag refuses when a member would hit an outside take'  [harness]  @ 743-756
  @case 'group drag with Alt duplicates the block and reselects the copies'  [harness]  @ 760-778
  @case 'loop to item brackets the take under the arrange cursor'  [harness]  @ 784-800
  @case 'loop to item takes the selection over the cursor, and spans a block'  [harness]  @ 804-821
  @case 'a cursor-driven replace leaves nothing selected'  [harness]  @ 825-837
  @case 'a replace of a selected take hands the selection to the replacement'  [harness]  @ 841-856
  @case 'a replace of a selection away from the cursor leaves the cursor alone'  [harness]  @ 860-872
  @case 'with advance-by-length armed, a drop advances by the take it placed'  [harness]  @ 878-891
  @case 'advance-by-length reads the clipped length, not the slot length'  [harness]  @ 895-908
  @case 'a second Ctrl-` puts the drop advance back on arrangeAdvanceBy'  [harness]  @ 912-926
  @case 'qnToRow / rowToQN are inverses through beatPerRow'  [harness]  @ 930-939

